create or replace function public.ensure_organization_owner_membership() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.organization_members(organization_id,user_id,role,joined_at) values(new.id,new.owner_id,'owner',now()) on conflict do nothing; return new; end $$;
drop trigger if exists ensure_organization_owner_membership on public.organizations;
create trigger ensure_organization_owner_membership after insert on public.organizations for each row execute function public.ensure_organization_owner_membership();
create or replace function public.submit_job_application(p_job_id uuid,p_cv_url text,p_cover_letter text,p_answers jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid; v_item jsonb; begin if auth.uid() is null then raise exception 'Sign in first'; end if; if not exists(select 1 from public.job_postings j where j.id=p_job_id and j.status='open' and (j.closes_at is null or j.closes_at>=now())) then raise exception 'This role is not accepting applications'; end if; insert into public.job_applications(job_posting_id,applicant_id,cv_url,cover_letter_text) values(p_job_id,auth.uid(),p_cv_url,nullif(trim(p_cover_letter),'')) returning id into v_id; for v_item in select * from jsonb_array_elements(coalesce(p_answers,'[]'::jsonb)) loop if exists(select 1 from public.screening_questions q where q.id=(v_item->>'questionId')::uuid and q.job_posting_id=p_job_id) then insert into public.job_question_answers(application_id,question_id,question_kind,answer_value) values(v_id,(v_item->>'questionId')::uuid,'screening',coalesce(v_item->>'value','')); end if; end loop; return v_id; end $$;
revoke all on function public.submit_job_application(uuid,text,text,jsonb) from public,anon; grant execute on function public.submit_job_application(uuid,text,text,jsonb) to authenticated;